  PLI.LR=bakePlate('LR',[[0,.2,.78,.66],[.2,.42,.55,.42],[.42,.64,.92,.82],[.64,.84,.66,.54],[.84,1,.84,.7]],1,'rgba(170,100,255,.95)',{x:1024,y:984,w:102,h:34,ang:-.3,pal:'R',ix:-.12},null,[[1196,884,70],[1208,700,44]]);
