    rimGlow(g,D,'rgba(190,120,255,1)',18,7);g.fillStyle='#160b3c';poly(g,D);g.fill();g.strokeStyle='#b890ff';g.lineWidth=9;g.lineJoin='round';poly(g,D);g.stroke();
    const gr=g.createLinearGradient(0,-102,0,102);gr.addColorStop(0,'#ffffff');gr.addColorStop(.5,'#f1e6ff');gr.addColorStop(1,'#a56bff');g.fillStyle=gr;g.shadowColor='#d9b5ff';g.shadowBlur=20;poly(g,D2);g.fill();
