    if(M.y<R){const s=-M.vy;M.y=R;if(M.vy<0)M.vy=-M.vy*.12;if(s>35&&M.wallCd<=0){wallHit(0,1,s);M.wallCd=.25}}
    if(M.y>hi){const s=M.vy;M.y=hi;if(M.vy>0)M.vy=-M.vy*.12;if(s>35&&M.wallCd<=0){wallHit(0,-1,s);M.wallCd=.25}}
