      if(smA>.02){const ps=P[s.side==='L'?'sL':'sR'];c.save();c.translate(0,48);c.scale(.3,.3);c.globalAlpha=smA*(.4+.4*s.ps);c.drawImage(pick(ps,.2).c,ps.ox-ps.ax,ps.oy-ps.ay,ps.w,ps.h);c.restore()}
