      if(f.ty===1){g.save();g.translate(f.x,f.y);g.rotate(f.r);g.globalCompositeOperation='lighter';g.globalAlpha=1-k;g.fillStyle='rgba(240,235,255,1)';g.fillRect(-f.s,-f.s*.32,f.s*2,f.s*.64);g.restore()}
